const makeSetRefs = (forwardedRef, localRef) => useCallback((el) => {
 if (typeof forwardedRef === 'function') {
 forwardedRef(el);
 }
 else if (forwardedRef) {
 forwardedRef.current = el;
 }
 localRef.current = el;
}, [forwardedRef]);

