","import React, { useEffect, useState } from "react";
import { NowRecordListConnected } from "@servicenow/react-components/NowRecordListConnected";
import { getCount } from "../services/api";
import KpiCard from "../components/KpiCard";
import DashboardLayout from "../components/DashboardLayout";
import "./app.css";

const DOC_TABLE = "x_2182380_pwcnow_employee_document";
const TRAIN_TABLE = "x_2182380_pwcnow_employee_training";

const App: React.FC = () => {
 const [pendingDocs, setPendingDocs] = useState<number>(0);
 const [overdue, setOverdue] = useState<number>(0);
 const [toReview, setToReview] = useState<number>(0);
 const [inTraining, setInTraining] = useState<number>(0);

 useEffect(() => {
 getCount(DOC_TABLE, "u_status=pending").then(setPendingDocs);
 getCount(
 TRAIN_TABLE,
 "u_status!=complete^u_due_date<javascript:gs.beginningOfToday()"
 ).then(setOverdue);
 getCount(DOC_TABLE, "u_status=submitted").then(setToReview);
 getCount(TRAIN_TABLE, "u_status=in_progress").then(setInTraining);
 }, []);

 return (
 <DashboardLayout
 title="HR Dashboard"
 subtitle="Employee document and training management"
 >
 <div className="kpi-grid">
 <KpiCard label="Pending Documents" value={pendingDocs} color="rgb(226, 125, 0)" />
 <KpiCard label="Overdue Training" value={overdue} color="rgb(200, 60, 54)" />
 <KpiCard label="Documents to Review" value={toReview} />
 <KpiCard label="In Training" value={inTraining} color="rgb(78, 169, 48)" />
 </div>
 <h3 className="section-title">Employee Documents</h3>
 <div className="list-container">
 <NowRecordListConnected
 table={DOC_TABLE}
 listTitle="Employee Documents"
 columns="number,u_employee,u_document_type,u_status,u_due_date,u_reviewed_by"
 hideHeader={true}
 limit={10}
 />
 </div>
 <h3 className="section-title">Employee Training</h3>
 <div className="list-container">
 <NowRecordListConnected
 table={TRAIN_TABLE}
 listTitle="Employee Training"
 columns="number,u_employee,u_training_name,u_status,u_due_date,u_completion_date"
 hideHeader={true}
 limit={10}
 />
 </div>
 </DashboardLayout>
 );
};

export default App;
